LESSON_JSON = "{\n \"id\": \"nonparamt2\",\n \"topicId\": \"nonparam-t2\",\n \"moduleId\": \"nonparam\",\n \"title\": \"Wilcoxon signed-rank and sign tests\",\n \"breadcrumb\": \"Non-parametric methods → Paired samples → Sign and signed-rank tests\",\n \"engine\": \"B\",\n \"engineName\": \"Pair, subtract, then use signs or signed ranks.\",\n \"version\": \"1.0\",\n \"status\": \"approved\",\n \"estMin\": 96,\n \"objectives\": [\n  \"Identify paired observations and construct differences in a stated direction.\",\n  \"Apply the sign test after omitting zero differences.\",\n  \"Apply Wilcoxon signed-rank by ranking absolute nonzero differences and restoring signs.\",\n  \"Calculate rank sums and the no-tie null moments.\",\n  \"Choose between the two tests using the symmetry assumption.\"\n ],\n \"prereq\": [\n  {\n   \"id\": \"p1\",\n   \"name\": \"Paired observations\",\n   \"why\": \"Each difference must connect two measurements from the same or matched unit.\"\n  },\n  {\n   \"id\": \"p2\",\n   \"name\": \"Median and signs\",\n   \"why\": \"The sign test uses the direction of each nonzero difference.\"\n  },\n  {\n   \"id\": \"p3\",\n   \"name\": \"Ranking and average ranks\",\n   \"why\": \"The signed-rank test orders absolute differences and averages tied positions.\"\n  }\n ],\n \"traps\": [\n  \"Paired methods analyse within-pair differences; they are not for two unrelated groups.\",\n  \"Fix the subtraction order before interpreting positive and negative signs.\",\n  \"Zero differences are omitted from the effective sample size.\",\n  \"Sign test uses directions only; signed-rank also uses magnitude ranks.\",\n  \"Tied absolute differences receive average ranks.\",\n  \"Signed-rank's usual location interpretation needs symmetric differences; sign test does not.\"\n ],\n \"howto\": \"Work the paired-difference example before memorising formulas. First identify the pairing and subtraction direction. Use the sign test if symmetry is doubtful; use Wilcoxon signed-rank when the difference distribution is reasonably symmetric. For signed ranks, remove zeros, rank absolute differences, restore signs and verify the rank total.\",\n \"revision\": {\n  \"sheet\": [\n   \"Paired observations → form dᵢ=afterᵢ−beforeᵢ (or state another consistent direction).\",\n   \"Sign test: omit dᵢ=0; let m be nonzero count and X positive signs.\",\n   \"Under H₀: X∼Binomial(m,1/2); E(X)=m/2; Var(X)=m/4.\",\n   \"Exact two-sided sign-test p-value: double the smaller binomial tail, capped at 1.\",\n   \"Wilcoxon: omit zero differences under the common convention; rank |dᵢ|; average tied ranks; restore signs.\",\n   \"W⁺=sum positive ranks; W⁻=sum negative ranks; total ranks=m(m+1)/2 (also with midranks).\",\n   \"No-tie E(W⁺)=m(m+1)/4; Var(W⁺)=m(m+1)(2m+1)/24.\",\n   \"Signed-rank assumes symmetric paired differences for its usual location interpretation.\",\n   \"Sign test does not require symmetry; it is less sensitive because it discards magnitude ordering.\",\n   \"Independent groups → do not use either paired procedure; consider Mann–Whitney for two groups.\"\n  ],\n  \"cards\": [\n   [\n    \"Design\",\n    \"Paired samples\"\n   ],\n   [\n    \"Sign test\",\n    \"Count positive vs negative nonzero differences\"\n   ],\n   [\n    \"Sign null\",\n    \"Binomial(m, 1/2)\"\n   ],\n   [\n    \"Sign variance\",\n    \"m/4\"\n   ],\n   [\n    \"Signed-rank\",\n    \"Rank |d|, then restore signs\"\n   ],\n   [\n    \"Rank total\",\n    \"m(m+1)/2\"\n   ],\n   [\n    \"E(W⁺)\",\n    \"m(m+1)/4\"\n   ],\n   [\n    \"Var(W⁺), no ties\",\n    \"m(m+1)(2m+1)/24\"\n   ],\n   [\n    \"Extra assumption\",\n    \"Symmetric paired differences for signed-rank\"\n   ]\n  ],\n  \"tricks\": [\n   \"Remove zeros before defining m.\",\n   \"Use absolute differences for ranking, not signed differences.\",\n   \"Check W⁺+W⁻ against m(m+1)/2.\"\n  ],\n  \"shortcuts\": [\n   \"Sign test: X~Binomial(m, 1/2).\",\n   \"Signed-rank no-tie variance: m(m+1)(2m+1)/24.\",\n   \"Sign test: count positive signs among m nonzero pairs; zeros do not enter m.\"\n  ],\n  \"remember\": [\n   \"Same units twice → paired test.\",\n   \"Skewed differences → sign test is safer than signed-rank.\"\n  ]\n },\n \"refs\": [\n  {\n   \"title\": \"Nonparametric Statistical Methods\",\n   \"where\": \"Paired-sample procedures\",\n   \"site\": \"Hollander, Wolfe and Chicken\",\n   \"url\": \"\",\n   \"type\": \"Textbook\",\n   \"free\": false,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Standard treatment of sign and Wilcoxon signed-rank procedures.\"\n  },\n  {\n   \"title\": \"NIST/SEMATECH e-Handbook of Statistical Methods\",\n   \"where\": \"Nonparametric methods\",\n   \"site\": \"NIST\",\n   \"url\": \"https://www.itl.nist.gov/div898/handbook/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Applied reference for nonparametric inference.\"\n  },\n  {\n   \"title\": \"Penn State STAT 415\",\n   \"where\": \"Nonparametric tests\",\n   \"site\": \"Penn State\",\n   \"url\": \"https://online.stat.psu.edu/stat415/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Accessible supporting material for paired tests.\"\n  }\n ],\n \"mastery\": {\n  \"minQ\": 10,\n  \"pass\": 80,\n  \"draw\": 10,\n  \"fmtMin\": {\n   \"numeric\": 70,\n   \"multi\": 70\n  },\n  \"diffMix\": {\n   \"easy\": 3,\n   \"moderate\": 5,\n   \"hard\": 2\n  },\n  \"noHints\": true,\n  \"retestDays\": 7,\n  \"note\": \"Proposed platform settings, not an NTA rule. Overall 80%, with 70% floors on numerical and multi-statement items, answered without hints.\"\n },\n \"provenance\": \"No direct June 2026 paired-sample anchor. The paper's Q42 is an independent-sample Mann–Whitney problem; it is used only as a contrast to show why paired differences require a different procedure. Worked calculations use constructed paired differences. The verifier checks sign counts, zero exclusion, rank sums, tied average ranks, null moments and the binomial model.\",\n \"scenes\": [\n  {\n   \"kind\": \"foundation\",\n   \"id\": \"s0\",\n   \"mins\": 7,\n   \"title\": \"Start with the paired design\",\n   \"objective\": \"Recognise paired observations and construct a difference.\",\n   \"ask\": {\n    \"q\": \"The same 10 people are measured before and after. Independent or paired?\",\n    \"nudge\": \"Does each after-value belong to a particular before-value?\"\n   },\n   \"body\": [\n    \"A paired study follows the same unit twice, or deliberately matches units into pairs. The analysis must preserve the link within each pair.\",\n    \"Choose a consistent subtraction, such as after minus before. Positive values then mean an increase and negative values mean a decrease. The subtraction convention changes the direction label, not the two-sided evidence.\"\n   ],\n   \"items\": [\n    {\n     \"ask\": \"The same patient is measured twice. What is the design?\",\n     \"recall\": \"Paired; each patient supplies a linked pair.\",\n     \"refresh\": [\n      \"Pairing means two observations belong to the same unit or a matched unit. Keep the link when analysing the data.\",\n      \"Do not treat the two columns as independent samples. Form one within-pair difference for each unit.\"\n     ]\n    },\n    {\n     \"ask\": \"What does after minus before equal to −2 mean?\",\n     \"recall\": \"The after measurement fell by 2 units.\",\n     \"refresh\": [\n      \"The defined difference is d=after−before, so the after measurement is lower by two units. The negative sign records a decrease under this subtraction convention.\",\n      \"Write the subtraction order before calculating any differences. Use the same order for every participant; reversing it changes all signs but does not change the two-sided conclusion.\"\n     ]\n    },\n    {\n     \"ask\": \"What is the median of −3, −1, 2, 4?\",\n     \"recall\": \"(−1+2)/2=0.5.\",\n     \"refresh\": [\n      \"Sort the values before finding the median. With an odd number of observations, the median is the single middle value; with an even number, it is the average of the two central values.\",\n      \"For −3, −1, 2, 4, the two central values are −1 and 2. Their average is (−1+2)/2=0.5. The median is a measure of centre, not necessarily one of the observed values.\"\n     ]\n    }\n   ]\n  },\n  {\n   \"kind\": \"intuition\",\n   \"id\": \"s1\",\n   \"mins\": 7,\n   \"title\": \"Use direction before magnitude\",\n   \"objective\": \"Understand the distinction between the sign and signed-rank procedures.\",\n   \"ask\": {\n    \"q\": \"Which test uses only whether a difference is positive or negative?\",\n    \"nudge\": \"Ignore how large the changes are.\"\n   },\n   \"body\": [\n    \"Suppose six people improve and two worsen. The sign test records six plus signs and two minus signs. It does not distinguish a one-point improvement from a ten-point improvement.\",\n    \"Wilcoxon signed-rank keeps the same signs but also ranks the absolute nonzero differences. A large change receives a larger rank. This can add information when the difference distribution is symmetric.\"\n   ],\n   \"scenario\": {\n    \"teaser\": \"A paired before-and-after health outcome.\",\n    \"title\": \"A hospital treatment study\",\n    \"body\": [\n     \"A hospital records pain scores for the same patients immediately before and after treatment. Each patient supplies a pair of observations, so the two columns are linked. The scale is ordered, but adjacent categories need not be equally spaced. A sign test uses whether each patient's score rose or fell. A signed-rank test also ranks the absolute size of each nonzero change, and its usual location interpretation assumes symmetric paired differences. Patients with no change contribute no direction to either calculation.\"\n    ],\n    \"q\": \"Why is an independent two-sample test inappropriate here?\",\n    \"answer\": \"Each patient's before and after values are linked; the analysis must preserve the pairing.\"\n   }\n  },\n  {\n   \"kind\": \"explore\",\n   \"id\": \"s2\",\n   \"mins\": 6,\n   \"title\": \"Make paired differences visible\",\n   \"objective\": \"Build signed differences before ranking.\",\n   \"ask\": {\n    \"q\": \"If d=after−before, what does d=+3 mean?\",\n    \"nudge\": \"The after measurement is three units higher.\"\n   },\n   \"viz\": {\n    \"type\": \"rank-null\",\n    \"caption\": \"Rank positions of absolute paired differences; tied magnitudes share average ranks, while their signs remain attached separately.\"\n   },\n   \"body\": [\n    \"Consider paired differences 4, −1, 3, −2, 5, −6, using after minus before. There are three positive and three negative differences, so the sign test has a balanced count.\",\n    \"For signed ranks, order the absolute differences: 1, 2, 3, 4, 5, 6. Their ranks are 1, 2, 3, 4, 5, 6. Positive ranks sum to 4+3+5=12; negative ranks sum to 1+2+6=9.\"\n   ]\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s3\",\n   \"mins\": 9,\n   \"title\": \"The sign test\",\n   \"objective\": \"Set up the binomial test after removing zero differences.\",\n   \"ask\": {\n    \"q\": \"What is the null probability of a positive sign?\",\n    \"nudge\": \"Under no directional tendency, positive and negative are equally likely.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"def\",\n     \"h\": \"Remove zero differences\",\n     \"body\": \"A zero difference has neither a positive nor a negative sign. Omit it. Let m be the number of nonzero pairs, with X positive signs.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Null model\",\n     \"body\": \"Under H₀ of no median directional shift, X follows Binomial(m, 1/2). Thus E(X)=m/2 and Var(X)=m/4.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Exact two-sided probability\",\n     \"body\": \"Add binomial probabilities at least as extreme in both tails. For an observed x, use 2×P(X≤min(x,m−x)), capped at 1, under the symmetric null.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Assumption and scope\",\n     \"body\": \"The sign test does not require a symmetric distribution of differences. It tests the median of the paired-difference distribution against zero, under the usual independent-pair sampling model.\"\n    }\n   ],\n   \"flow\": {\n    \"title\": \"Choose the paired rank procedure\",\n    \"alt\": \"Paired differences with plausible symmetry lead to Wilcoxon signed-rank; doubtful symmetry leads to the sign test.\",\n    \"nodes\": [\n     {\n      \"id\": \"a\",\n      \"r\": 0,\n      \"c\": 1,\n      \"label\": \"Paired observations\",\n      \"kind\": \"start\"\n     },\n     {\n      \"id\": \"b\",\n      \"r\": 1,\n      \"c\": 1,\n      \"label\": \"Form differences\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"c\",\n      \"r\": 2,\n      \"c\": 1,\n      \"label\": \"Check symmetry\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"d\",\n      \"r\": 3,\n      \"c\": 0,\n      \"label\": \"Symmetric: signed-rank\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"e\",\n      \"r\": 3,\n      \"c\": 2,\n      \"label\": \"Skewed: sign test\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"f\",\n      \"r\": 4,\n      \"c\": 1,\n      \"label\": \"Interpret paired change\",\n      \"kind\": \"end\"\n     }\n    ],\n    \"edges\": [\n     {\n      \"from\": \"a\",\n      \"to\": \"b\"\n     },\n     {\n      \"from\": \"b\",\n      \"to\": \"c\"\n     },\n     {\n      \"from\": \"c\",\n      \"to\": \"d\"\n     },\n     {\n      \"from\": \"c\",\n      \"to\": \"e\"\n     },\n     {\n      \"from\": \"d\",\n      \"to\": \"f\"\n     },\n     {\n      \"from\": \"e\",\n      \"to\": \"f\"\n     }\n    ],\n    \"note\": \"Both tests preserve pairing; signed-rank additionally uses magnitude ranks and needs symmetry for its usual location interpretation.\"\n   }\n  },\n  {\n   \"kind\": \"worked\",\n   \"id\": \"s4\",\n   \"mins\": 10,\n   \"title\": \"Worked example: sign and signed ranks\",\n   \"objective\": \"Calculate both procedures from the same six nonzero paired differences.\",\n   \"ask\": {\n    \"q\": \"Why do both methods use six observations here?\",\n    \"nudge\": \"All six differences are nonzero; no pair is discarded.\"\n   },\n   \"problem\": \"Paired differences (after−before) are 4, −1, 3, −2, 5, −6. Calculate the sign count and Wilcoxon signed-rank sums.\",\n   \"steps\": [\n    {\n     \"say\": \"Count the signs.\",\n     \"math\": \"Positive=3; negative=3; m=6\",\n     \"why\": \"The sign test ignores the size of each change.\"\n    },\n    {\n     \"say\": \"Rank the absolute differences.\",\n     \"math\": \"|d|: 1, 2, 3, 4, 5, 6 → ranks 1, 2, 3, 4, 5, 6\",\n     \"why\": \"There are no ties in the absolute differences, so the ranks are consecutive.\"\n    },\n    {\n     \"say\": \"Add the positive ranks.\",\n     \"math\": \"W⁺=4+3+5=12\",\n     \"why\": \"The positive differences are 4, 3 and 5.\"\n    },\n    {\n     \"say\": \"Add the negative ranks.\",\n     \"math\": \"W⁻=1+2+6=9\",\n     \"why\": \"The negative differences are −1, −2 and −6.\"\n    },\n    {\n     \"say\": \"Check the total.\",\n     \"math\": \"W⁺+W⁻=12+9=21=6×7/2\",\n     \"why\": \"The sum of ranks 1 through 6 is 21. The smaller signed-rank sum is 9.\"\n    }\n   ],\n   \"after\": \"The sign test sees three positive and three negative signs. Signed-rank also uses the ordering of the magnitudes.\"\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s5\",\n   \"mins\": 3,\n   \"title\": \"Pause and retrieve\",\n   \"objective\": \"Recall the design and null model.\",\n   \"intro\": \"Try each answer before revealing it.\",\n   \"items\": [\n    {\n     \"q\": \"Which test uses only plus and minus signs?\",\n     \"a\": \"The sign test.\"\n    },\n    {\n     \"q\": \"What happens to zero differences?\",\n     \"a\": \"Omit them from the sign count.\"\n    },\n    {\n     \"q\": \"Under the sign-test null, what is P(positive)?\",\n     \"a\": \"One half.\"\n    },\n    {\n     \"q\": \"What does signed-rank add?\",\n     \"a\": \"Ranks of absolute nonzero differences.\"\n    },\n    {\n     \"q\": \"Which test needs symmetric paired differences for its usual location interpretation?\",\n     \"a\": \"Wilcoxon signed-rank.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"completion\",\n   \"id\": \"s6\",\n   \"mins\": 8,\n   \"title\": \"Complete a signed-rank calculation\",\n   \"objective\": \"Fill the missing rank and total.\",\n   \"problem\": \"Six nonzero absolute differences have distinct ranks 1 to 6. The positive differences have ranks 2, 4 and 6. Find W⁺ and W⁻.\",\n   \"steps\": [\n    {\n     \"say\": \"Add positive ranks.\",\n     \"blank\": {\n      \"prompt\": \"W⁺=2+4+6=…\",\n      \"answer\": \"12\",\n      \"accept\": [\n       \"12.0\"\n      ],\n      \"hint\": \"Add the three positive ranks.\"\n     },\n     \"why\": \"W⁺ is the sum of ranks carrying a positive sign.\"\n    },\n    {\n     \"say\": \"Find the total rank sum.\",\n     \"blank\": {\n      \"prompt\": \"1+2+3+4+5+6=…\",\n      \"answer\": \"21\",\n      \"accept\": [\n       \"21.0\"\n      ],\n      \"hint\": \"Use m(m+1)/2 with m=6.\"\n     },\n     \"why\": \"All ranks must be allocated to either positive or negative differences.\"\n    },\n    {\n     \"say\": \"Subtract to find the negative sum.\",\n     \"blank\": {\n      \"prompt\": \"W⁻=21−12=…\",\n      \"answer\": \"9\",\n      \"accept\": [\n       \"9.0\"\n      ],\n      \"hint\": \"The positive and negative rank sums must add to 21.\"\n     },\n     \"why\": \"This checks the two signed-rank sums.\"\n    }\n   ],\n   \"after\": \"For m distinct nonzero absolute differences, W⁺+W⁻=m(m+1)/2.\",\n   \"ask\": {\n    \"q\": \"Why are zero differences removed before ranking?\",\n    \"nudge\": \"A zero has no positive or negative sign and is excluded under the common convention.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s7\",\n   \"mins\": 8,\n   \"title\": \"Wilcoxon signed-rank test\",\n   \"objective\": \"Rank magnitudes and state the symmetry condition.\",\n   \"ask\": {\n    \"q\": \"Why rank |d| rather than d itself?\",\n    \"nudge\": \"The sign is kept separately; rank the size of each nonzero change.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"step\",\n     \"h\": \"Procedure\",\n     \"body\": \"Compute paired differences dᵢ. Under the common Wilcoxon convention, omit zero differences. Rank |dᵢ| from smallest to largest, assigning average ranks to ties. Restore each original sign and sum positive and negative ranks.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Rank totals\",\n     \"body\": \"W⁺ is the sum of positive ranks and W⁻ is the sum of negative ranks. With m nonzero differences, W⁺+W⁻=m(m+1)/2; average ranks preserve the same total when ties occur.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Null moments without ties\",\n     \"body\": \"For W⁺ under H₀: E(W⁺)=m(m+1)/4 and Var(W⁺)=m(m+1)(2m+1)/24.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Assumption\",\n     \"body\": \"The paired differences should be independent across pairs and approximately symmetric about the null location for the signed-rank test's usual location interpretation. The sign test does not require symmetry.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Zeros and ties\",\n     \"body\": \"The common Wilcoxon convention omits zero differences and ranks the remaining absolute differences. Tied absolute differences receive average ranks; use a tie-adjusted variance or an appropriate exact method.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s8\",\n   \"mins\": 8,\n   \"title\": \"Guided transfer: choose between the tests\",\n   \"objective\": \"Select the procedure from the shape and information available.\",\n   \"problem\": \"A researcher has 14 independent pairs of ordered before-and-after scores. The paired differences are strongly skewed. The question asks whether the median change is zero. Which test is safer, and why?\",\n   \"hints\": [\n    \"Identify the paired structure and target.\",\n    \"Check whether the signed-rank symmetry condition is plausible.\",\n    \"Choose the method whose assumptions match the information.\"\n   ],\n   \"answer\": \"The sign test is safer because it uses only the direction of nonzero differences and does not require symmetric paired differences. Remove zero differences before the binomial calculation.\",\n   \"check\": \"Do not choose signed-rank solely because the data are paired; inspect the difference distribution.\",\n   \"solution\": [\n    {\n     \"say\": \"Preserve the paired design.\",\n     \"math\": \"dᵢ=afterᵢ−beforeᵢ\",\n     \"why\": \"The target is a one-sample location question on paired differences.\"\n    },\n    {\n     \"say\": \"Check the stronger assumption.\",\n     \"math\": \"Strong skewness → symmetry is doubtful\",\n     \"why\": \"The signed-rank test's usual location interpretation relies on symmetric differences.\"\n    },\n    {\n     \"say\": \"Select the sign procedure.\",\n     \"math\": \"X∼Binomial(m, 1/2) under H₀\",\n     \"why\": \"The sign test uses directions and does not require symmetry.\"\n    }\n   ],\n   \"scenario\": {\n    \"teaser\": \"A paired confidence rating before and after a course.\",\n    \"title\": \"Student confidence study\",\n    \"body\": [\n     \"A university measures the same students' confidence before and after a short course. Each student has a linked pair, and the analyst defines the difference as after minus before. Positive values then mean confidence increased. The sign test uses only the direction of nonzero differences. Wilcoxon signed-rank also uses the ordering of their magnitudes and therefore needs a reasonably symmetric distribution of paired differences for its usual location interpretation. The researcher checks the difference distribution before choosing the procedure.\"\n    ],\n    \"q\": \"Why is the symmetry check relevant before using signed-rank?\",\n    \"answer\": \"Its usual location interpretation assumes a symmetric distribution of paired differences.\"\n   },\n   \"ask\": {\n    \"q\": \"Which assumption distinguishes signed-rank from the sign test?\",\n    \"nudge\": \"Check whether paired differences are reasonably symmetric.\"\n   }\n  },\n  {\n   \"kind\": \"trapcheck\",\n   \"id\": \"s9\",\n   \"mins\": 6,\n   \"title\": \"Six statements to challenge\",\n   \"objective\": \"Separate the two paired rank procedures.\",\n   \"intro\": \"Mark each claim true or false before reading the reason.\",\n   \"items\": [\n    {\n     \"claim\": \"Both sign and signed-rank tests are for paired observations.\",\n     \"tf\": true,\n     \"why\": \"True. Both operate on within-pair differences.\"\n    },\n    {\n     \"claim\": \"The sign test ranks absolute differences.\",\n     \"tf\": false,\n     \"why\": \"False. That is the additional step in Wilcoxon signed-rank.\"\n    },\n    {\n     \"claim\": \"Zero differences count as positive signs.\",\n     \"tf\": false,\n     \"why\": \"False. They are omitted from the sign test's effective sample size.\"\n    },\n    {\n     \"claim\": \"Wilcoxon signed-rank usually assumes symmetric paired differences.\",\n     \"tf\": true,\n     \"why\": \"True. Symmetry supports its usual location interpretation.\"\n    },\n    {\n     \"claim\": \"Tied absolute differences receive average ranks.\",\n     \"tf\": true,\n     \"why\": \"True. Average ranks preserve the total rank sum.\"\n    },\n    {\n     \"claim\": \"The sign test requires normally distributed differences.\",\n     \"tf\": false,\n     \"why\": \"False. It requires independent pairs and the sign-probability null, not normality.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s10\",\n   \"mins\": 8,\n   \"title\": \"Guided calculation: zeros and signs\",\n   \"objective\": \"Recalculate the sign-test sample size after zero differences.\",\n   \"problem\": \"Paired differences are 2, 0, −1, 3, 0, 4, −2, 1. Find m and the positive and negative counts.\",\n   \"hints\": [\n    \"Identify and set aside zero differences.\",\n    \"Count only the nonzero signs.\",\n    \"Check positive plus negative equals m.\"\n   ],\n   \"answer\": \"There are two zero differences, so m=6. Positive=4 and negative=2.\",\n   \"check\": \"The nonzero count is 8−2=6, and 4+2=6.\",\n   \"solution\": [\n    {\n     \"say\": \"Remove zero differences.\",\n     \"math\": \"8 total pairs−2 zero differences=6 nonzero pairs\",\n     \"why\": \"Zero has neither a positive nor a negative direction.\"\n    },\n    {\n     \"say\": \"Count the remaining signs.\",\n     \"math\": \"Positive: 2, 3, 4, 1 → 4; negative: −1, −2 → 2\",\n     \"why\": \"Count each nonzero difference once.\"\n    },\n    {\n     \"say\": \"Check the count.\",\n     \"math\": \"4+2=6=m\",\n     \"why\": \"The sign counts must equal the effective sample size.\"\n    }\n   ],\n   \"ask\": {\n    \"q\": \"How do zero differences affect the sign-test sample size?\",\n    \"nudge\": \"They are omitted from m.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s11\",\n   \"mins\": 6,\n   \"title\": \"Inference and test selection\",\n   \"objective\": \"Connect exact and approximate inference with assumptions.\",\n   \"ask\": {\n    \"q\": \"What is the sign-test variance under H₀?\",\n    \"nudge\": \"For a binomial variable, variance is mpq.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"formula\",\n     \"h\": \"Sign test\",\n     \"body\": \"X∼Binomial(m, 1/2), E(X)=m/2 and Var(X)=m/4. Use the exact binomial tail for small m; a normal approximation may be used for sufficiently large m with an appropriate continuity correction.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Signed-rank normal approximation\",\n     \"body\": \"Without ties or zeros, E(W⁺)=m(m+1)/4 and Var(W⁺)=m(m+1)(2m+1)/24. Standardise W⁺ using these moments when a normal approximation is justified.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Decision guide\",\n     \"body\": \"Paired data with symmetric differences and useful magnitude ordering: Wilcoxon signed-rank. Paired data with doubtful symmetry, or only directional information trusted: sign test. Independent groups: neither; consider Mann–Whitney for two groups.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s12\",\n   \"mins\": 3,\n   \"title\": \"Second recall\",\n   \"objective\": \"Retrieve formulas under exam conditions.\",\n   \"intro\": \"Answer, then reveal.\",\n   \"items\": [\n    {\n     \"q\": \"Sign-test null distribution?\",\n     \"a\": \"Binomial(m, 1/2), where m excludes zeros.\"\n    },\n    {\n     \"q\": \"Sign-test variance?\",\n     \"a\": \"m/4.\"\n    },\n    {\n     \"q\": \"No-tie signed-rank null mean for W⁺?\",\n     \"a\": \"m(m+1)/4.\"\n    },\n    {\n     \"q\": \"No-tie signed-rank variance?\",\n     \"a\": \"m(m+1)(2m+1)/24.\"\n    },\n    {\n     \"q\": \"What is the extra signed-rank assumption?\",\n     \"a\": \"Symmetry of paired differences for its usual location interpretation.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"summary\",\n   \"id\": \"s13\",\n   \"mins\": 3,\n   \"title\": \"What you should now be able to do\",\n   \"objective\": \"Choose and calculate the two paired-sample nonparametric tests.\",\n   \"body\": [\n    \"Identify paired data and define differences in a stated direction.\",\n    \"For the sign test, omit zero differences, count positive signs and use Binomial(m, 1/2).\",\n    \"For signed-rank, rank absolute nonzero differences with average ranks for ties, then sum ranks by sign.\",\n    \"Use no-tie null moments only when their conditions apply; account for ties in inference.\",\n    \"Choose signed-rank when symmetry is plausible; choose sign test when it is not.\"\n   ],\n   \"ask\": {\n    \"q\": \"What is the key decision when choosing between sign and signed-rank?\",\n    \"nudge\": \"Whether symmetry of paired differences is plausible.\"\n   }\n  },\n  {\n   \"kind\": \"quiz\",\n   \"id\": \"s14\",\n   \"mins\": 4,\n   \"title\": \"Mastery test\",\n   \"objective\": \"Demonstrate the paired-test skills independently.\",\n   \"setId\": \"nonparam_t2_mastery\"\n  }\n ]\n}\n"
